# c405, Taeyang/Codex. Partial wheat lots; preserve inherited variable-price market slots.
# No opponent ID, replay, seed or future opponent observation is used.
_C405_ENABLED = True
_C405_PARENT = _C396_PARENT
_C405_ROUTE_ACTION = _C365_CA_NS['Chassis']._route_action
_C405_DEBTS = {}
_C405_REPORT = {}
_C405_SEAT = 0

def _c405_route_action(self, route, step):
    action = _C405_ROUTE_ACTION(self, route, step)
    due = _C405_DEBTS.get((_C405_SEAT, step, route))
    if _C405_ENABLED and due:
        index, original_quantity, quantity = due
        orders = action.get('market') or []
        if index < len(orders) and orders[index] == ['SELL', 'WHEAT', original_quantity]:
            action = _c396_copy.deepcopy(action)
            action['market'][index] = ['SELL', 'WHEAT', original_quantity - quantity]
            _C405_REPORT['c405_settled'] += 1
        else:
            raise RuntimeError('c405 scheduled sale identity mismatch')
    return action

def _c405_parent(observation, configuration=None):
    global _C405_SEAT
    t = int(observation['step']); seat = int(observation['player']); _C405_SEAT = seat
    if t == 0:
        _C405_DEBTS.clear(); _C405_REPORT.clear()
        _C405_REPORT.update(c405_changes=0, c405_units=0, c405_settled=0,
                            c405_budget_declines=0, c405_capacity_declines=0)
    action = _C405_PARENT(observation, configuration)
    for key in list(_C405_DEBTS):
        if key[0] == seat and key[1] <= t:
            del _C405_DEBTS[key]
    if not _C405_ENABLED or not 144 <= t < 647 or t % 24 == 23:
        return action
    cfg = dict(configuration or {})
    if any(cfg.get(k, v) != v for k, v in [('boardSize',10),('turnsPerDay',24),
            ('shedCapacity',100),('maxMarketOrdersPerTurn',10)]):
        return action
    orders = action.get('market') or []
    wheat = [(i,o) for i,o in enumerate(orders) if len(o)>=3 and o[1]=='WHEAT'
             and o[0] in ('BUY_PRODUCT','SELL')]
    if len(wheat)!=1 or wheat[0][1][0]!='BUY_PRODUCT' :
        return action
    index, buy = wheat[0]; quantity = int(buy[2])
    if quantity <= 0:
        return action
    native = _C358_IMPL.chassis; route = native.players[seat]['route']
    future = native.routes[route][t+1]
    legs = [(i,o) for i,o in enumerate(future.get('market') or [])
            if len(o)>=3 and o[1]=='WHEAT' and o[0] in ('BUY_PRODUCT','SELL')]
    if len(legs)!=1 or legs[0][1][0]!='SELL':
        return action
    future_quantity = int(legs[0][1][2])
    quantity = min(quantity, future_quantity)
    if quantity <= 0:
        return action
    # Do not move any inherited order across a rival's simultaneous slot.
    # The new sale must follow the buy; empty earlier slots stay empty.
    slot = next((i for i in range(index+1,len(orders)) if not orders[i]),len(orders))
    if slot >= 10:
        return action
    # Never accelerate a purchase needed by a scheduled field pickup.
    for frame in (action, future):
        if any(c[:2]==['PICKUP','WHEAT'] for c in [frame.get('farmer') or ['PASS']]
               + list(frame.get('hands') or [])):
            return action
    # Existing conservative budget bounds all ten rival market orders. Do not
    # borrow against this turn's sale proceeds or sell existing feed reserves.
    if not _C365_CA_NS['_r97_budget'](observation, orders):
        _C405_REPORT['c405_budget_declines'] += 1
        return action
    projected = projected_shed(action, FarmView(observation))
    if sum(max(0,int(q)) for q in projected.values()) + sum(
            max(0,int(o[2])) for o in orders if len(o)>=3 and o[0] in ('BUY_PRODUCT','BUY_ANIMAL')) > 100:
        _C405_REPORT['c405_capacity_declines'] += 1
        return action
    result = _c396_copy.deepcopy(action)
    sale = ['SELL','WHEAT',quantity]
    if slot < len(result['market']):
        result['market'][slot] = sale
    else:
        result['market'].append(sale)
    # All original purchases are fully cash-funded by _r97_budget above.
    # Only fixed-price HIRE/BUY_SEED may move right. Never cross a product
    # order, animal/land commitment or empty slot: those indices are protected.
    while slot > index + 1:
        left = result['market'][slot-1]
        fixed = left == ['HIRE'] or (len(left)==3 and left[0]=='BUY_SEED'
                  and type(left[2]) is int and left[2]>0)
        if not fixed:
            break
        result['market'][slot], result['market'][slot-1] = left, result['market'][slot]
        slot -= 1
    _C405_DEBTS[(seat,t+1,route)] = (legs[0][0],future_quantity,quantity)
    _C405_REPORT['c405_changes'] += 1; _C405_REPORT['c405_units'] += quantity
    return result

if _C405_ENABLED:
    _C365_CA_NS['Chassis']._route_action = _c405_route_action
_C396_PARENT = _c405_parent
_C405_ENTRY = agent
_C405_TELEMETRY = {}

def agent(observation, configuration=None):
    action = _C405_ENTRY(observation, configuration)
    _C405_TELEMETRY.clear(); _C405_TELEMETRY.update(_C396_TELEMETRY)
    _C405_TELEMETRY.update(_C405_REPORT)
    return action

agent.telemetry = _C405_TELEMETRY
c405_submission_agent = agent

# c406: public shadow coverage expansion. Taeyang/Codex 2026-09-23.
# Adds reviewed public sources 222,276,279; all embedded original source notices are retained.
# Only the hypothesis set changes. Source IDs below are internal dictionary
# keys, never a runtime opponent identifier or an input from Kaggle.
