if _C406_ENABLED:
    _C396_SOURCES.update(_C406_ADDED_SOURCES)
c406_submission_agent = agent

# c407: public sale coverage with a market-supply invariant.
# Kaggriculture 1.32.7 ignores $1 sales when adding market inventory.
# Equal sold units can therefore leave unequal public supply after reordering.
# Keep the parent's own execution checks and additionally preserve that supply
# for every surviving public hypothesis. No new orders or field edits.
_C407_ENABLED = True
def _c407_market(farms, privates, market, orders, configuration, own):
    f = _c396_copy.deepcopy(farms)
    p = _c396_copy.deepcopy(privates)
    m = _c396_copy.deepcopy(market)
    state = [_c396_box(observation=_c396_box(farms=f, market=m, private=p[i]),
                      action=dict(market=orders[i])) for i in (0, 1)]
    _C396_ENGINE['_process_market'](state, _c396_box(configuration=configuration))
    cash = [x['money'] for x in f]
    own_farm = dict(f[own])
    own_farm.pop('money')
    # _c396_response already requires result[2:] == base[2:] under all models.
    return cash[own], cash[own]-cash[1-own], p[own], own_farm, m['inventory']
if _C407_ENABLED:
    _c396_market = _c407_market
c407_submission_agent = agent

# c408: repair existing feed supply, compact sheep service and late overflow.
# Source-derived hooks retain native budget, slot and overnight-loss checks.
_C408_ENABLED = True
_C408_FEED = True
_C408_CARGO = True
_C408_HYGIENE = True
_C408_PARENT = agent
_C408_REPORT = {}
_C408_TELEMETRY = {}
_C408_NS = _C365_CA_NS


if _C408_ENABLED and _C408_FEED:
    _C408_NS['_C408_REPORT'] = _C408_REPORT
    exec('"""Injected into the existing public body; all data are current own observations."""\n\ndef _c408_farmer_pickup(tape, at):\n    command = tape[at].get(\'farmer\') or [\'PASS\']\n    quantity = max(0, int(command[2]) if len(command) > 2 else 1)\n    remaining = 0\n    for t in range(at + 1, min(len(tape), (at // 24 + 1) * 24)):\n        c = tape[t].get(\'farmer\') or [\'PASS\']\n        if c[0] == \'DROP\' or c[:2] in ([\'PICKUP\', \'WHEAT\'], [\'PLACE\', \'WHEAT\']):\n            break\n        remaining += c[0] == \'FEED\'\n    return max(quantity, remaining)\n\n\ndef _c408_required_stock(obs, action, farm, private):\n    step = int(obs[\'step\'])\n    player = int(obs[\'player\'])\n    native = _IMPL.chassis.players[player]\n    at = step + 1\n    tape = _IMPL.chassis.routes[2 if at >= 648 else native[\'route\']]\n    following_orders = tape[at].get(\'market\') or []\n    # The existing lookahead covered only a full queue and two pickup turns.\n    # A hiring turn can acquire later sale overlays; reserve through its next\n    # two field phases, which execute before either turn\'s market purchases.\n    horizon = 3 if (len(following_orders) >= 9 or any(o and o[0] == \'HIRE\' for o in following_orders)) else 1\n    native_need = 0\n    for t in range(at, min(695, at + horizon)):\n        route = _IMPL.chassis.routes[2 if t >= 648 else native[\'route\']]\n        frame = route[t]\n        for actor, c in enumerate([frame.get(\'farmer\') or [\'PASS\'], *(frame.get(\'hands\') or [])]):\n            if c[:2] == [\'PICKUP\', \'WHEAT\']:\n                native_need += (_c408_farmer_pickup(route, t) if actor == 0 else\n                                max(0, int(c[2]) if len(c) > 2 else 1))\n    # Supplemental sheep workers do not occur in the native tape. Their\n    # carried grain and completed current-turn feeds must be counted exactly.\n    extra_need = 0\n    if step // 24 < 29:\n        state = _V233_STATES.get(player) or {}\n        for actor, targets in state.get(\'workers\', {}).items():\n            if actor >= len(private[\'inventories\']):\n                continue\n            hungry = sum(isinstance(farm[\'tiles\'][y][x], dict)\n                         and farm[\'tiles\'][y][x].get(\'animal\') == \'SHEEP\'\n                         and not farm[\'tiles\'][y][x].get(\'fed_today\') for x, y in targets)\n            extra_need += max(0, hungry - private[\'inventories\'][actor].get(\'WHEAT\', 0))\n    return native_need + extra_need\n\n\ndef _r97_supply(obs,action):\n    step=int(obs[\'step\']);player=int(obs[\'player\']);day=step//24\n    if not 144<=step<695:return action\n    native=_IMPL.chassis.players[player]\n    future=_IMPL.chassis.routes[2 if step+1>=648 else native[\'route\']][step+1]\n    commands=[future.get(\'farmer\') or [\'PASS\'],*(future.get(\'hands\') or [])]\n    following=_IMPL.chassis.routes[2 if step+2>=648 else native[\'route\']][step+2]\n    next_orders=future.get(\'market\') or []\n    prefund=0\n    if len(next_orders)==10 and not any(o[:2] in ([\'BUY_PRODUCT\',\'WHEAT\'],[\'SELL\',\'WHEAT\']) for o in next_orders):\n        later=[following.get(\'farmer\') or [\'PASS\'],*(following.get(\'hands\') or [])]\n        demand=lambda cs:sum(max(0,int(c[2]) if len(c)>2 else 1) for c in cs if c[:2]==[\'PICKUP\',\'WHEAT\'])\n        if demand(later):prefund=demand(commands)+demand(later)\n    orders=action.get(\'market\') or []\n    if len(orders)>10 or not _r97_budget(obs,orders):\n        _R97_REPORT[\'supply_budget_declines\']+=1;return action\n    farm,private=_PLANNER_NS[\'_clone_state\'](obs[\'farms\'][player],obs[\'private\'])\n    for actor,c in enumerate([action.get(\'farmer\') or [\'PASS\'],*(action.get(\'hands\') or [])][:len(private[\'inventories\'])]):\n        _PLANNER_NS[\'_apply_unit_action\'](farm,private,actor,c,10,day,24,100)\n    positions=[tuple(farm[\'farmer\']),*map(tuple,farm[\'hands\'])];night=step%24==23\n    access=((4,4),(5,4),(4,5),(5,5))\n    if night:positions=[(4,4)]\n    else:\n        for order in orders:\n            if order and order[0]==\'HIRE\':positions.append(min(access,key=lambda p:(positions.count(p),access.index(p))))\n    need=sum(max(0,int(c[2]) if len(c)>2 else 1) for pos,c in zip(positions,commands) if pos in access and c[:2]==[\'PICKUP\',\'WHEAT\'])\n    need=max(need,prefund,_c408_required_stock(obs,action,farm,private))\n    _C408_REPORT[\'c408_supply_calls\']+=1\n    if not need:return action\n    original_stock,original_buys,_=_r97_market_stock(private[\'shed\'],orders)\n    original_final,original_loss=_r97_delivery(original_stock,private,night)\n    if original_final.get(\'WHEAT\',0)>=need:return action\n    result=copy.deepcopy(action);proposed=result[\'market\'];blocked=False\n    def project(candidate):\n        stock,buys,sales=_r97_market_stock(private[\'shed\'],candidate)\n        final,loss=_r97_delivery(stock,private,night)\n        safe=all(buys.get(i,0)>=q for i,q in original_buys.items()) and all(q<=original_loss.get(item,0) for item,q in loss.items())\n        return final,sales,safe\n    # Hold an existing grain sale first. Preserve all order indices and every\n    # originally funded buy; no extra overnight overflow may be introduced.\n    for index in range(len(proposed)-1,-1,-1):\n        if proposed[index][:2]!=[\'SELL\',\'WHEAT\']:continue\n        final,sales,safe=project(proposed);shortage=max(0,need-final.get(\'WHEAT\',0))\n        if not shortage:break\n        sold=sales.get(index,0)\n        if not sold:continue\n        old=proposed[index][2];proposed[index][2]=max(0,sold-shortage)\n        after,_,safe=project(proposed)\n        if not safe or after.get(\'WHEAT\',0)<=final.get(\'WHEAT\',0):proposed[index][2]=old\n    final,_,safe=project(proposed);shortage=max(0,need-final.get(\'WHEAT\',0))\n    if shortage:\n        last_sale=max((i for i,o in enumerate(proposed) if o[:2]==[\'SELL\',\'WHEAT\']),default=-1)\n        index=next((i for i in range(len(proposed)-1,last_sale,-1) if proposed[i][:2]==[\'BUY_PRODUCT\',\'WHEAT\']),None)\n        if index is not None:proposed[index][2]=max(0,int(proposed[index][2]))+shortage\n        elif len(proposed)<10:proposed.append([\'BUY_PRODUCT\',\'WHEAT\',shortage])\n        else:_R97_REPORT[\'supply_slot_declines\']+=1;return action\n    final,_,safe=project(proposed)\n    if not safe or final.get(\'WHEAT\',0)<need:\n        _R97_REPORT[\'supply_capacity_declines\']+=1;return action\n    if not _r97_budget(obs,proposed):\n        _R97_REPORT[\'supply_budget_declines\']+=1;return action\n    if prefund:\n        _R97_REPORT[\'supply_prefund_changes\']+=1\n        _R97_REPORT[\'supply_prefund_units\']+=max(0,final.get(\'WHEAT\',0)-original_final.get(\'WHEAT\',0))\n    if step<288:\n        _R97_REPORT[\'supply_early_changes\']+=1\n        _R97_REPORT[\'supply_early_units\']+=max(0,final.get(\'WHEAT\',0)-original_final.get(\'WHEAT\',0))\n    _R97_REPORT[\'supply_guard_changes\']+=1\n    _R97_REPORT[\'supply_grain_protected\']+=final.get(\'WHEAT\',0)-original_final.get(\'WHEAT\',0)\n    _R97_REPORT[\'supply_buy_units\']+=sum(max(0,int(o[2])) for o in proposed if o[:2]==[\'BUY_PRODUCT\',\'WHEAT\'])-sum(max(0,int(o[2])) for o in orders if o[:2]==[\'BUY_PRODUCT\',\'WHEAT\'])\n    return result\ndef _c408_compact_worker(obs,actor,targets):\n    if len(targets)!=6:\n        return _SL_WORKER(obs,actor,targets)\n    farm=obs[\'farms\'][obs[\'player\']];private=obs[\'private\'];step=int(obs[\'step\'])\n    pos=tuple(farm[\'hands\'][actor-1]);inv=private[\'inventories\'][actor]\n    needed=[];hungry=0\n    for target in targets:\n        x,y=target;t=farm[\'tiles\'][y][x]\n        if not isinstance(t,dict) or t.get(\'animal\')!=\'SHEEP\':\n            return _SL_WORKER(obs,actor,targets)\n        if not t[\'fed_today\']:hungry+=1\n        if not t[\'fed_today\'] or not t[\'cared_today\']:needed.append(target)\n    home=_v219_home(pos)\n    if hungry>inv.get(\'WHEAT\',0):\n        if private[\'shed\'].get(\'WHEAT\',0)>0:\n            _C408_REPORT[\'c408_partial_pickup\']+=1\n            return _v219_walk(pos,home) or [\'PICKUP\',\'WHEAT\',min(hungry-inv.get(\'WHEAT\',0),private[\'shed\'][\'WHEAT\'])]\n        if not inv.get(\'WHEAT\',0):\n            return _v219_walk(pos,home) or [\'PASS\']\n        _C408_REPORT[\'c408_partial_service\']+=1\n    if needed:\n        path=_sl_path(pos,needed)\n        current=farm[\'tiles\'][pos[1]][pos[0]]\n        if pos in targets and isinstance(current,dict) and current.get(\'fed_today\') and current.get(\'cared_today\') and current.get(\'fertilizer_available\'):\n            travel=_sl_dist(pos,path[0])+sum(_sl_dist(a,b) for a,b in zip(path,path[1:]))\n            work=sum(not farm[\'tiles\'][y][x][\'fed_today\'] for x,y in path)+sum(not farm[\'tiles\'][y][x][\'cared_today\'] for x,y in path)\n            delivery=_sl_dist(path[-1],_v219_home(path[-1]))+1 if step//24==29 else 0\n            remaining=min((step//24+1)*24,719)-step\n            if 1+travel+work+delivery<=remaining:\n                _SL_REPORT[\'collect\']+=1\n                return [\'COLLECT_FERTILIZER\']\n        target=path[0];t=farm[\'tiles\'][target[1]][target[0]]\n        return _v219_walk(pos,target) or ([\'FEED\'] if not t[\'fed_today\'] else [\'CARE\'])\n    # Essential work is complete. Collect what can still reach the shed on\n    # the final day; on earlier days the normal midnight deposit is sufficient.\n    remaining=719-step if step//24==29 else 24-step%24\n    tasks=[]\n    for target in targets:\n        t=farm[\'tiles\'][target[1]][target[0]]\n        if not t.get(\'fertilizer_available\'):continue\n        dist=_sl_dist(pos,target)\n        ret=_sl_dist(target,_v219_home(target))+1 if step//24==29 else 0\n        if dist+1+ret<=remaining:tasks.append((dist,tuple(target)))\n    if tasks:\n        _,target=min(tasks)\n        command=_v219_walk(pos,target) or [\'COLLECT_FERTILIZER\']\n        _SL_REPORT[\'collect\']+=command==[\'COLLECT_FERTILIZER\']\n        return command\n    if inv.get(\'FERTILIZER\',0):\n        return _v219_walk(pos,home) or [\'PLACE\',\'FERTILIZER\',inv[\'FERTILIZER\']]\n    return [\'PASS\']', _C408_NS)
    _C408_NS['_VT_WORKER'] = _C408_NS['_c408_compact_worker']


def _c408_normalize(obs, action):
    # Normalize only actions that the exact field interpreter proves inert.
    # This does not advance a route or claim to recover a missed harvest.
    own = int(obs['player'])
    f, p = _C408_NS['_PLANNER_NS']['_clone_state'](obs['farms'][own], obs['private'])
    commands = [list(action.get('farmer') or ['PASS']),
                *[list(c) for c in (action.get('hands') or [])]]
    seed_demand = {}
    for c in commands:
        if len(c) > 1 and c[0] == 'PLANT':
            seed_demand[c[1]] = seed_demand.get(c[1], 0) + 1
    blocked = {k for k, n in seed_demand.items() if n > p['seeds'].get(k, 0)}
    inert = {'WATER', 'HARVEST', 'FEED', 'CARE', 'COLLECT_FERTILIZER',
             'PICKUP', 'PLACE', 'DROP', 'DIG', 'FERTILIZE'}
    changed = False
    for actor, c in enumerate(commands[:len(p['inventories'])]):
        if len(c) > 1 and c[0] == 'PLANT' and c[1] in blocked:
            continue
        before = _c358_copy.deepcopy((f, p)) if c[0] in inert else None
        _C408_NS['_PLANNER_NS']['_apply_unit_action'](f, p, actor, c, 10, int(obs['step']) // 24, 24, 100)
        if before is not None and before == (f, p):
            commands[actor] = ['PASS']
            _C408_REPORT['c408_inert_removed'] += 1
            changed = True
    return dict(action, farmer=commands[0], hands=commands[1:]) if changed else action


_C408_PRE_SETTLEMENT = _C405_PARENT


def _c408_pre_settlement(obs, configuration=None):
    action = _C408_PRE_SETTLEMENT(obs, configuration)
    if not _C408_ENABLED:
        return action
    if _C408_CARGO:
        # The inherited overflow guard precedes later field/market overlays.
        # Recheck the final field commands without changing post-dawn stocks.
        repaired = _C408_NS['_ov_apply'](obs, action)
        if repaired != action:
            _C408_REPORT['c408_late_overflow'] += 1
        action = repaired
    if _C408_HYGIENE:
        action = _c408_normalize(obs, action)
    return action


if _C408_ENABLED:
    _C405_PARENT = _c408_pre_settlement


def agent(observation, configuration=None):
    if int(observation['step']) == 0:
        _C408_REPORT.clear()
        _C408_REPORT.update(c408_supply_calls=0, c408_partial_pickup=0,
                           c408_partial_service=0, c408_late_overflow=0,
                           c408_inert_removed=0, c408_errors=0)
    result = _C408_PARENT(observation, configuration)
    _C408_TELEMETRY.clear()
    _C408_TELEMETRY.update(getattr(_C408_PARENT, 'telemetry', {}))
    _C408_TELEMETRY.update(_C408_REPORT)
    return result


agent.telemetry = _C408_TELEMETRY
c408_submission_agent = agent

